  if (typeof input.fontFamily === 'string' && Object.hasOwn(fontFamilies, input.fontFamily)) {
    const adjusted = applyFontFamily(tokens, input.fontFamily as FontFamily);
    tokens.fontFamily = adjusted.fontFamily;
